#import "ZNEmbeddedAssets.h"

static NSString * const kPresetAtlasBase64 = @"";

UIImage *ZNEmbeddedImage(NSString *name) {
    static UIImage *atlas;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        NSData *data = [[NSData alloc] initWithBase64EncodedString:kPresetAtlasBase64 options:0];
        atlas = [UIImage imageWithData:data scale:1.0];
    });
    if (!atlas.CGImage) return nil;
    NSArray<NSString *> *names = @[@"sunset",@"cyberpunk",@"noir",@"film",@"lomo",@"vibrant",@"liquid",@"glitch",@"vintage",@"nebula",@"city",@"minimal"];
    NSUInteger idx = [names indexOfObject:name];
    if (idx == NSNotFound) return nil;
    const CGFloat cellW = 64.0, cellH = 39.0;
    CGRect rect = CGRectMake((idx % 4) * cellW, (idx / 4) * cellH, cellW, cellH);
    CGImageRef crop = CGImageCreateWithImageInRect(atlas.CGImage, rect);
    if (!crop) return nil;
    UIImage *image = [UIImage imageWithCGImage:crop scale:1.0 orientation:UIImageOrientationUp];
    CGImageRelease(crop);
    return image;
}
